/* ---------- Eval results ---------- */
/* an eval suite's latest run: one bar segment per case, the pass count against the run before, and the cases, all or
   just the failed ones. A failed case opens to show what was expected and what came back, with a fix that reruns it.
   Marks are the vivid status colours (a tick in the mark green, a failed case's sign in the mark red); words keep the text
   colours. The card keeps no room for what is to come: it grows and shrinks with its list (grow()) */
.evr{width:100%;max-width:440px;margin:0 auto;padding:6px;display:flex;flex-direction:column}
.evr-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-2) 10px 10px}
.evr-ht{display:flex;flex-direction:column;min-width:0}
.evr-ht b{font-weight:500;font-size:14px}
.evr-st{font-size:12.5px}
.evr-run{flex:none}
.evr-run .spin{width:10px;height:10px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
:is(.evr,.evr-vs,.evr-jg) :is(.ib,.pill):active,:root[data-style="clean"] :is(.evr,.evr-vs,.evr-jg) .ib:active,:root [data-style="clean"] :is(.evr,.evr-vs,.evr-jg) .ib:active,:root [data-style="clean"]:is(.evr,.evr-vs,.evr-jg) .ib:active{transform:none}
/* the line under the bars (Running 3 of 8, then 7 of 8 passed) sits as far under the bars as over the hairline below it
   (owner, 22 Nov) */
.evr-sum{display:flex;flex-direction:column;gap:var(--dm-s-3);padding:var(--dm-s-3) 10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.evr-segs{display:flex;gap:3px}
.evr-segs i{flex:1;height:6px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-rail);transition:background .3s}
.evr-segs i.pass{background:var(--dm-ok-mark)}
.evr-segs i.fail{background:var(--dm-bad-mark)}
.evr-segs i.run{background:var(--dm-accent-mark,var(--dm-accent));animation:evrrun 1s ease-in-out infinite}
@keyframes evrrun{50%{opacity:.4}}
.evr-nums{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:20px;font-size:13px}
.evr-pass.shim{font-size:inherit}
.evr-dl:empty{display:none}
.evr-tabs{padding:10px 10px var(--dm-s-1)}
.evr-tabs .n{color:var(--dm-muted);margin-left:2px}
.evr-tabs .n:empty{display:none}
.evr-list{display:flex;flex-direction:column}
/* a case folds away when the filter hides it, and stays hidden once shut so nothing measures it */
.evr-w.shut>div{visibility:hidden;transition:visibility 0s var(--dm-t)}
.evr-i{display:flex;flex-direction:column;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));transition:background .2s}
.evr-r{display:flex;align-items:center;gap:10px;width:100%;min-height:38px;padding:6px 10px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;text-align:left;color:var(--dm-fg)}
.evr-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.evr-g .spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.evr-i.pass .evr-g{color:var(--dm-ok-mark)}
.evr-i.fail .evr-g{color:var(--dm-bad-mark)}
.evr-n{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.evr-i.queued .evr-n{color:var(--dm-fg2)}
.evr-tm{font-size:12px;color:var(--dm-muted)}
.evr-ch{display:grid;color:var(--dm-muted)}
.evr-ch svg{transition:transform .32s var(--dm-ease)}
.evr-r[aria-expanded="false"] .evr-ch svg{transform:rotate(-90deg)}
.evr-i.fail{background:var(--dm-bad-bg)}.evr-i.fail :is(.evr-tm,.evr-kv .k){color:var(--dm-fg2)}
.evr-d.shut>div{visibility:hidden;transition:visibility 0s var(--dm-t)}
.evr-dd{display:flex;flex-direction:column;gap:var(--dm-s-1);padding:0 10px 10px 36px;font-size:12.5px}
.evr-kv{display:flex;gap:var(--dm-s-2)}
.evr-kv .k{width:58px;flex:none;color:var(--dm-muted)}
.evr-kv .bad{color:var(--dm-bad)}
/* a white button on the tinted row: a hairline edge and no shadow (owner, 18 Nov: buttons cast none) */
/* the fix sits under a hairline, apart from the details above it (owner, 22 Nov); the hairline is a step of the words' own
   colour, so it reads on the row's tint */
.evr-dd .evr-kv:has(+.evr-fix),.evr-vs-d .evr-vs-kv:has(+.pill){padding-bottom:var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,currentColor 12%,transparent)}
.evr-fix{align-self:flex-start;margin-top:var(--dm-s-2);background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.evr-fix:hover{background:var(--dm-surface);box-shadow:var(--dm-on-tint-btn-h)}}
/* nothing to show under a filter: the empty state (the lab's, lab/clean): a small sketch of the list on a white card, the
   title, one muted line and a button back to every case */
.evr-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px 16px 12px;text-align:center}
.evr-em[hidden]{display:none}
.evr-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.evr-em>span:not(.evr-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.evr-em .pill{margin-top:12px}
.evr-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.evr-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:50%;background:var(--dm-ghost);box-shadow:0 16px 0 var(--dm-ghost),0 32px 0 var(--dm-ghost-2)}
.evr-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost);box-shadow:0 16px 0 var(--dm-ghost),0 32px 0 var(--dm-ghost-2)}
:root:not([data-style="soft"],[data-style="clean"]) .evr-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{border-radius:0}
/* Clean (owner, 17 and 18 Nov): its content 16px in from each edge, a failed case's row clear of any red fill (its sign and
   its Got stay red) and grey under the pointer, its corners following the card's */
:root[data-style="clean"] .evr-r,:root [data-style="clean"] .evr-r,:root [data-style="clean"].evr-r{border-radius:calc(var(--dm-r-card) - 6px)}
:root[data-style="clean"] .evr-i.fail,:root [data-style="clean"] .evr-i.fail,:root [data-style="clean"].evr-i.fail{border-radius:calc(var(--dm-r-card) - 6px)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .evr-i.fail:hover,:root [data-style="clean"] .evr-i.fail:hover,:root [data-style="clean"].evr-i.fail:hover{background:var(--dm-row)}}
:root[data-style="clean"] .evr-fix,:root [data-style="clean"] .evr-fix,:root [data-style="clean"].evr-fix{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .evr-fix:hover,:root [data-style="clean"] .evr-fix:hover,:root [data-style="clean"].evr-fix:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .evr-fix:active,:root [data-style="clean"] .evr-fix:active,:root [data-style="clean"].evr-fix:active{box-shadow:var(--dm-btn2-press)}
/* a pressed button never goes blank (owner, 18 Nov): Run turns to its disabled look at once */
:root[data-style="clean"] :is(.evr-run,.evr-vs-run)[disabled],:root [data-style="clean"] :is(.evr-run,.evr-vs-run)[disabled],:root [data-style="clean"]:is(.evr-run,.evr-vs-run)[disabled]{transition:none}

DM.def('eval-results', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{play}', I('play','xs'));
  // eight checks on the pricing page's copy. The price check fails after the copy agent's latest edit, until it's fixed
  const K = [
    { n:'Names the Pro seat limit', tm:'0.6s' },
    { n:'Prices match the billing table', tm:'0.9s', bad:true, exp:'$24 a seat, billed yearly', got:'$29 a seat, billed yearly', src:'Billing table, Pro row' },
    { n:'Mentions the yearly discount', tm:'0.5s' },
    { n:'Makes no “unlimited” claims', tm:'0.4s' },
    { n:'Team plan lists SSO', tm:'0.5s' },
    { n:'Reads at grade 8 or below', tm:'0.7s' },
    { n:'One call to action per plan', tm:'0.5s' },
    { n:'Free plan says no card is needed', tm:'0.6s' }
  ].map(k => ({ ...k, s:'pass' }));
  const LAST = 8;
  const list = $('.evr-list', r), segs = $('.evr-segs', r), pass = $('.evr-pass', r), dl = $('.evr-dl', r), st = $('.evr-st', r), run = $('.evr-run', r), none = $('.evr-none', r), sg = $('.evr-tabs .seg2', r);
  // no room is kept for the cases a filter hides or the empty state: the card eases to what it shows (owner, 17 Nov)
  c.offs.push(grow($('.evr', r)));
  $('.evr-all', none).onclick = () => $('[data-v="all"]', sg).click();
  const G = { run:'<span class="spin"></span>', pass:I('ok','xs'), fail:I('alert','xs'), queued:'<span class="dot"></span>' };
  // a button whose words change is as wide as its words and eases to its new width (owner, 18 Nov)
  const relabel = (b, h) => { const w0 = b.getBoundingClientRect().width; b.innerHTML = h; const w1 = b.getBoundingClientRect().width, cs = getComputedStyle(b);
    if (!REDUCE && w0 && Math.abs(w1 - w0) > .5) b.animate([{ width:w0 + 'px' }, { width:w1 + 'px' }], { duration:(parseFloat(cs.getPropertyValue('--dm-t')) || .34) * 1000, easing:cs.getPropertyValue('--dm-ease').trim() || 'ease' }); };
  let filter = 'all', busy = false, ran = false;
  K.forEach((k, i) => {
    k.w = html(`<div class="fold evr-w"><div><div class="evr-i" role="listitem"></div></div></div>`); k.el = $('.evr-i', k.w); k.i = i; list.appendChild(k.w);
    k.seg = document.createElement('i'); segs.appendChild(k.seg);
  });
  // a case's row: a failed one is a button that opens what was expected and what came back
  function paint(k, fresh){
    const open = k.s === 'fail' && k.open;
    k.el.className = 'evr-i ' + k.s;
    const g = `<span class="evr-g">${G[k.s]}</span><span class="evr-n">${k.n}</span><span class="evr-tm num">${k.s === 'pass' || k.s === 'fail' ? k.tm : ''}</span>`;
    k.el.innerHTML = k.s === 'fail'
      ? `<button class="evr-r" aria-expanded="${!!open}">${g}<span class="evr-ch">${I('chev-d','xs')}</span></button><div class="fold evr-d${open ? '' : ' shut'}"><div><div class="evr-dd"><span class="evr-kv"><span class="k">Expected</span><span>${k.exp}</span></span><span class="evr-kv"><span class="k">Got</span><span class="bad">${k.got}</span></span><span class="evr-kv"><span class="k">Source</span><span>${k.src}</span></span><button class="pill sm evr-fix">Use $24 and rerun</button></div></div></div>`
      : `<div class="evr-r">${g}</div>`;
    if (k.s === 'fail'){
      const d = $('.evr-d', k.el); d.inert = !open;
      $('.evr-r', k.el).onclick = () => { k.open = !k.open; $('.evr-r', k.el).setAttribute('aria-expanded', k.open); d.classList.toggle('shut', !k.open); d.inert = !k.open; };
      $('.evr-fix', k.el).onclick = () => fix(k);
    }
    if (fresh) enter($('.evr-g', k.el));
    k.seg.className = k.s;
  }
  function counts(){
    const p = K.filter(k => k.s === 'pass').length, f = K.filter(k => k.s === 'fail').length, done = K.every(k => k.s === 'pass' || k.s === 'fail');
    swap(pass, done ? `${p} of ${K.length} passed` : busy ? `Running ${K.filter(k => k.s === 'pass' || k.s === 'fail').length + 1} of ${K.length}` : 'Running the case again');
    pass.classList.toggle('shim', !done);
    const d = !ran || !done ? '' : p < LAST ? `${LAST - p} fewer than the last run` : 'All passing';
    if (dl.textContent !== d){ dl.textContent = d; dl.className = 'tag evr-dl ' + (p < LAST ? 'bad' : 'ok'); if (d) enter(dl); }
    $('[data-v="all"] .n', sg).textContent = K.length; $('[data-v="fail"] .n', sg).textContent = f;
    show();
  }
  // All shows every case; Failed folds the others away
  function show(){
    K.forEach(k => { const on = filter === 'all' || k.s === 'fail' || k.again; k.w.classList.toggle('shut', !on); k.w.inert = !on; });
    none.hidden = !(filter === 'fail' && !K.some(k => k.s === 'fail' || k.again));
  }
  seg(sg, v => { filter = v; show(); });
  K.forEach(k => paint(k)); counts();
  // a run checks the cases one after another; the price check fails until the copy is fixed
  run.onclick = () => c.run(async () => {
    if (busy) return; busy = true; ran = true; run.disabled = true; relabel(run, '<span class="spin"></span>Running');
    K.forEach(k => { k.s = 'queued'; k.open = false; paint(k); }); counts();
    for (const k of K){
      k.s = 'run'; paint(k, true); counts();
      await c.wait(500);
      k.s = k.bad ? 'fail' : 'pass'; paint(k, true); counts();
    }
    busy = false; run.disabled = false; relabel(run, I('play','xs') + 'Run again'); swap(st, 'Copy agent · run just now');
  });
  // the fix changes the copy to the billing table's price and runs that case again
  function fix(k){
    if (busy) return;
    c.run(async () => {
      k.bad = false; k.open = false; k.again = true; k.s = 'run'; paint(k, true); counts();
      await c.wait(1000);
      k.s = 'pass'; paint(k, true); counts();
      // its pass shows in place for a moment before the Failed view lets it go
      await c.wait(900); k.again = false; show();
    });
  }
  // the preview's story: run the evals, see one fail against the last run, open it, take the fix, and see all eight pass
  c.story(async s => {
    await s.beat(3);
    await s.tap(run); s.away();
    await s.until(() => !busy); await s.beat(3);
    await s.tap($('[data-v="fail"]', sg)); s.away(); await s.beat(2);
    await s.tap($('.evr-i.fail .evr-r', r)); s.away(); await s.beat(3);
    await s.tap($('.evr-fix', r)); s.away();
    await s.until(() => K.every(k => k.s === 'pass')); await s.beat(2);
    await s.tap($('[data-v="all"]', sg)); s.away(); await s.beat(2);
  });
});
